#if KLODA_S3_NATIVE
import Foundation

// One explicit foreground request, generated bytes only, separate receipts and opt-in from user backups.
enum IosS3Diagnostic {
  static func run(profiles: IosS3Profiles, captured: IosS3Capture, request: UUID, root: URL,
    current: @escaping () -> Bool) throws -> [String: Any] {
    let provider = profiles.journal.provider
    guard !Thread.isMainThread, !captured.profile.target.prefix.isEmpty else { throw IosS3Failure(code: "invalid_request") }
    func check() throws { guard current(), try profiles.current(captured) else { throw IosS3Failure(code: "candidate_stale") } }
    try check()
    let journal = try IosS3Journal(url: root.appendingPathComponent("kloda-" + provider + "-diagnostic.sqlite"), provider: provider)
    try journal.recoverInterrupted(); try journal.setEnabled(false)
    try journal.database.execute("CREATE TABLE IF NOT EXISTS s3_test_request(id TEXT PRIMARY KEY)")
    try journal.database.execute("INSERT INTO s3_test_request VALUES(?)", values: [request.uuidString.lowercased()])
    try journal.prepareProfile(captured.profile.target); try journal.confirmProfile(captured.profile.target)
    let testProfiles = IosS3Profiles(journal: journal), snapshots = try IosFilesSnapshot.s3(provider)
    var retained = false
    let (name, file) = try snapshots.createStaging()
    defer { try? file.close(); if !retained { try? snapshots.discard(name) } }
    do {
      try check()
      let data = Data((0..<4097).map { UInt8($0 % 251) })
      let hash = IosS3Target.hash(data)
      try file.write(contentsOf: data); try file.synchronize()
      try snapshots.sealStaging(name, sha256: hash, size: Int64(data.count), cancelled: { (try? check()) == nil })
      try journal.setEnabled(true)
      let id = String(name.dropLast(9)), installation = try journal.installation()
      let job = IosS3Job(id: id, installation: installation, context: try journal.context(), target: captured.profile.target,
        source: UUID().uuidString.lowercased(), reference: "diagnostic/" + request.uuidString.lowercased(), revision: hash,
        sourceGeneration: request.uuidString.lowercased(), snapshot: name, key: "objects/" + installation + "/" + id,
        sha256: hash, size: Int64(data.count), name: "kloda-test.bin", logicalPath: "kloda-test.bin")
      let descriptor = try snapshots.open(name, sha256: hash, size: job.size, cancelled: { (try? check()) == nil })
      defer { try? descriptor.close() }
      try check(); try journal.insert(job); retained = true
      try IosS3Publisher(profiles: testProfiles).publish(job, snapshot: descriptor.fileDescriptor,
        currentSource: { try check(); return true }, completedSource: check)
      try check()
      let restored = try IosS3Download(profiles: testProfiles, snapshots: snapshots, check: check).stage(job.id)
      defer { try? snapshots.discard(restored) }
      let readback = try snapshots.open(restored, sha256: hash, size: job.size, cancelled: { (try? check()) == nil })
      defer { try? readback.close() }
      guard try readback.readToEnd() == data else { throw IosS3Failure(code: "verification_failed") }
      try check(); try journal.setEnabled(false); try snapshots.discard(name); retained = false
      return ["provider": provider, "state": "completed", "id": id, "size": data.count, "sha256": hash]
    } catch {
      try journal.setEnabled(false)
      throw error
    }
  }
}
#endif
